from requests.packages import urllib3
urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

# Importamos todos los paquetes (o librerías o bibliotecas o libraries) que sean
# necesarios para que funcione nuestro script

# "requests" lo usaremos para la conexión con la API vía web
import requests
# "json" los usaremos para manejar la respuesta de la API
import json
# "pandas" es un paquete popular para manipular (entre otras cosas) hojas de cálculo
# PD: el agregado de "as pd" (que no es obligatorio) nos indica que le estamos dando un "apodo"
#     lo cual nos va a permitir llamar a sus métodos de una manera más corta ("pd" en vez de "pandas") y
#     es la forma usual en la que lo van a encontrar en casi cualquier script
import pandas as pd

# Vamos a obtener un listado de CUITs para consultar sus deudas
# desde una hoja de Excel que tengo en mi propio Drive
# en el path "/content/drive/MyDrive/Colab Notebooks/Lista bancos.xlsx"
df_bancos = pd.read_excel('/content/drive/MyDrive/Colab Notebooks/CharlaAPICPCECABA2025/Lista bancos.xlsx')
# Imprimo las primeras 5 filas (con el método head), para ver si importé bien la hoja
print(df_bancos.head())

# Con las CUIT almacenadas en el DataFrame "df_bancos" estamos casi listos para lanzar la consulta a la API
#
# Aclaraciones previas:
#   1) https://api.bcra.gob.ar es el servidor de la API
#   2) CentralDeDeudores/v1.0/Deudas es el endpoint de la API que queremos usar
#   3) usamos una f-string de Python para practicar el concepto, pero igualmente
#      podemos concatenar, si nos resulta más cómodo, la variable "identificacion"
#      al final de la cadena que pasamos como primer parámetro a get()
#   4) get() es un método (una función) de requests (es estática ya que no requiere)
#      instanciar un objeto; permite conectarnos a un servidor vía el verbo GET
#   5) En cada vuelta del ciclo "for" llamamos a la API y guardamos la respuesta en otro DataFrame

df_final = pd.DataFrame()

for identificacion in df_bancos["CUIT"]:
  central_deudores = requests.get(f"https://api.bcra.gob.ar/CentralDeDeudores/v1.0/Deudas/{identificacion}", verify=False)
  # print(central_deudores.text)
  # Esta línea de arriba la dejamos comentada, pero si la descomentan van a ver varias líneas similares a esta:
